import { asNumber, useSearchParam } from '../../url/useSearchParam';

/** The id of the person whose editor is open in the person form, kept in the URL. */
export function useEditingPerson() {
  return useSearchParam('editPerson', asNumber);
}
import { useNavigate, useSearch } from '@tanstack/react-router';

/**
 * Read and write ONE search-param key.
 *
 * State that outlives a click lives in the URL, not in a parent component — a filter, a sort, a
 * toggle, which row is selected. The control that owns a key is a self-contained file, and whoever
 * reads the key does so directly. Search params are an open namespace (declared once in
 * routes/__root.tsx), so a new key needs no schema change.
 *
 *     const [status, setStatus] = useSearchParam('status', asString);
 */
export function useSearchParam<T>(
  key: string,
  decode: (raw: unknown) => T,
): [T, (value: T | undefined) => void] {
  const search = useSearch({ strict: false }) as Record<string, unknown>;
  const navigate = useNavigate();

  const set = (value: T | undefined) => {
    void navigate({
      to: '.', // stay on the current route; only the search changes
      // Only the one key changes; every other param is left exactly as it was, so two controls
      // never clobber each other.
      search: (prev: Record<string, unknown>) => {
        const next = { ...prev };
        if (value === undefined || value === '') {
          delete next[key];
        } else {
          next[key] = value;
        }
        return next;
      },
      replace: true,
    });
  };

  return [decode(search[key]), set];
}

export const asString = (raw: unknown): string => (typeof raw === 'string' ? raw : '');
export const asNumber = (raw: unknown): number | undefined => {
  const n = Number(raw);
  return raw === undefined || raw === '' || Number.isNaN(n) ? undefined : n;
};
export const asFlag = (raw: unknown): boolean => raw === 'true' || raw === true;
import { getJson } from '../../api/http';
import { sheetKey } from '../sheet/sheetQuery';

export type Grade = 'A' | 'B' | 'C';
export const GRADES: Grade[] = ['A', 'B', 'C'];

/**
 * `version` is raised on every edit; an edit names the version it loaded. `retiredFrom` (yyyy-mm-dd) is
 * set once the person is retired, which they are at once, whatever the date; null otherwise. `held` is whether
 * they are on hold: while held, their OPEN claims count in no live total.
 */
export type Person = { id: number; name: string; grade: Grade; grades: Graded[]; version: number; retiredFrom: string | null; held: boolean };

/** A grade a person was given from `from` (yyyy-mm-dd) on; null for the first, from the beginning of time. */
export type Graded = { from: string | null; grade: Grade };

/** The person's grade in force on the date (yyyy-mm-dd): the one with the latest from-date on or before it. */
export function gradeOn(person: Person | undefined, date: string): Grade | undefined {
  if (!person) return undefined;
  // No from-date sorts as '', before every date.
  const applying = person.grades.filter((g) => (g.from ?? '') <= date);
  return applying.reduce<Graded | undefined>((best, g) => (!best || (g.from ?? '') > (best.from ?? '') ? g : best), undefined)
    ?.grade ?? person.grade;
}

/** Under the sheet's key, so re-loading the sheet re-reads its people. */
export const peopleKey = (sheetId: string) => [...sheetKey(sheetId), 'people'] as const;

export const peopleQuery = (sheetId: string) => ({
  queryKey: peopleKey(sheetId),
  queryFn: () => getJson<Person[]>(`/api/sheets/${encodeURIComponent(sheetId)}/people`),
});
